SELECT COUNT(*) FROM "orderExecutions" oe 
JOIN orders o ON oe."Ord_Link" = o."ORD_STAMP"
WHERE o."exchSpot" IN (SELECT md_link FROM marketstats WHERE "MKT_STATS_MARK" = (SELECT MAX("MKT_STATS_MARK") FROM marketstats));

